  /// Durations and curves. Under Reduce Motion every transition becomes a cross-fade of motion.instant.
  public enum Motion {
    /// Hover, press, toggles.
    public static let instant: KetchMotion = KetchMotion(duration: 0.1, curve: (0.2, 0, 0, 1))

    /// Badges, row reveal, selection.
    public static let quick: KetchMotion = KetchMotion(duration: 0.18, curve: (0.2, 0, 0, 1))

    /// Panels, glass morphs, list inserts.
    public static let standard: KetchMotion = KetchMotion(duration: 0.26, curve: (0.2, 0, 0, 1))

    /// Sheets and the menu-bar popover arriving.
    public static let gentle: KetchMotion = KetchMotion(duration: 0.42, curve: (0.16, 1, 0.3, 1))

    /// A finished install settling in: slight overshoot.
    public static let emphasized: KetchMotion = KetchMotion(duration: 0.56, curve: (0.34, 1.36, 0.64, 1))
  }

